<script setup>import {computed} from 'vue';import {useStudy} from '../stores/study';import PageHeading from '../components/PageHeading.vue';import StatCard from '../components/StatCard.vue';import WeeklyChart from '../components/WeeklyChart.vue';import ProgressBar from '../components/ProgressBar.vue';import QuoteCard from '../components/QuoteCard.vue';const s=useStudy();const values=computed(()=>[{label:'周一',minutes:35},{label:'周二',minutes:50},{label:'周三',minutes:25},{label:'周四',minutes:65},{label:'周五',minutes:40},{label:'周六',minutes:80},{label:'今天',minutes:s.minutes.value}]);const cats=computed(()=>{const m={};s.tasks.value.filter(t=>t.done).forEach(t=>m[t.category]=(m[t.category]||0)+Number(t.minutes));return Object.entries(m).map(([name,minutes])=>({name,minutes}))});const total=computed(()=>values.value.reduce((n,d)=>n+d.minutes,0))</script><template><section><PageHeading eyebrow="YOUR PROGRESS" title="每一份努力都有迹可循" subtitle="回顾学习轨迹，看看自己已经走了多远。"/><div class="stats-grid"><StatCard label="今日专注" :value="s.minutes.value+' 分钟'" note="来自已完成任务" icon="◷"/><StatCard label="完成任务" :value="s.done.value.length+' 项'" note="今天的行动成果" icon="✓"/><StatCard label="任务完成率" :value="s.rate.value+'%'" note="继续保持好习惯" icon="↗"/></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><small class="eyebrow">WEEKLY OVERVIEW</small><h2>▥ 本周学习时长</h2></div><b class="chart-total">{{total}} 分钟</b></div><WeeklyChart :values="values"/><p class="muted">图表为演示数据；今天的时长根据已完成任务计算。</p></section><aside class="right-column"><div class="panel mini"><span class="mini-icon">◎</span><h3>本周小目标</h3><strong>{{Math.round(total/60*10)/10}} <small>小时</small></strong><ProgressBar :value="Math.min(100,Math.round(total/420*100))" label="距离 7 小时目标"/><p>每天积累一点，成长看得见。</p></div><QuoteCard quote="成功不是偶尔的一次努力，而是日复一日的坚持。" author="Study Buddy"/></aside></div><section class="panel category-panel"><div class="panel-heading"><div><small class="eyebrow">BY CATEGORY</small><h2>学习时间分布</h2></div></div><div v-if="cats.length" class="category-list"><div v-for="c in cats" :key="c.name" class="category-row"><span class="tag">{{c.name}}</span><div class="track"><div class="fill" :style="{width:(s.minutes.value?c.minutes/s.minutes.value*100:0)+'%'}"></div></div><b>{{c.minutes}} 分钟</b></div></div><p v-else class="muted">完成一些学习任务后，这里就会出现分类统计。</p></section></section></template>